import os
HEAD=lambda app:f'''<!doctype html><html data-app="{app}"><head><meta charset="utf-8"><link rel="stylesheet" href="../../../../packages/ui/src/tokens.css"><link rel="stylesheet" href="../../../../packages/ui/src/components.css"><link rel="stylesheet" href="v2.css"></head><body class="sm-app">'''
def wm(app,pre):return f'<span class="sm-wordmark"><img src="../../../../packages/ui/src/brand/{app}.svg"><span><span class="app">{pre}</span><span class="smith">Smith</span></span></span>'
def page(n,app,body):open(f"{n}.html","w").write(HEAD(app)+body+"</body></html>")
def top(app,pre,mid="",right=""):return f'<header class="sm-topbar">{wm(app,pre)}<span style="width:1px;height:20px;background:var(--line-2)"></span>{mid}<span class="sp"></span>{right}</header>'
RAIL=[("◫","Home"),("▤","Media"),("T","Text"),("CC","Captions"),("✦","Elements"),("◐","Filters"),("⇄","Transitions"),("♪","Audio")]
def rail(on):return '<nav class="rail">'+"".join(f'<a class="{"on" if l==on else ""}"><i>{i}</i>{l}</a>' for i,l in RAIL)+'</nav>'
proj='<div class="row"><b style="font-weight:600">Sunset skate edit</b><span class="sm-chip"><span style="width:6px;height:6px;border-radius:9px;background:var(--ok)"></span>Saved</span></div>'
undo='<button class="sm-btn sm-btn--ghost sm-btn--icon">↶</button><button class="sm-btn sm-btn--ghost sm-btn--icon">↷</button>'
canvas_=lambda extra="":f'<div class="canvas"><div class="scene"></div><div class="sun"></div><div class="figure"></div><div class="title sel">GOLDEN HOUR<span class="handle" style="left:-8px;top:-8px"></span><span class="handle" style="right:-8px;top:-8px"></span><span class="handle" style="left:-8px;bottom:-8px"></span><span class="handle" style="right:-8px;bottom:-8px"></span></div><div class="cap">this is <span class="hl">the</span> part</div>{extra}</div>'
PX=86
def timeline():
  T=[("CC","Captions","c",[(0.4,1.8,"wait for it…"),(2.4,2.1,"this is the part"),(4.7,2.6,"nobody expected"),(9,2.4,"follow for more")]),("T","Text","t",[(0,3,"GOLDEN HOUR")]),("▶","Video","v",[(0,5.2,"skate_intro.mp4"),(5.2,6.8,"trick_slowmo.mov")]),("♪","Music","a",[(0,12,"lofi_beat.mp3")])]
  r='<div class="ruler">'+"".join(f'<span style="left:{s*PX}px">0:{s:02d}</span>' for s in range(0,14))+'</div>'
  for ic,n,k,its in T:
    r+=f'<div class="tr"><div class="h"><span class="dim">{ic}</span>{n}</div><div class="lane">'+"".join(f'<div class="it {k} {"on" if l=="GOLDEN HOUR" else ""}" style="left:{s*PX}px;width:{d*PX-3}px"><span style="position:relative">{l}</span></div>' for s,d,l in its)+'</div></div>'
  bar='<div class="tlbar"><button class="sm-btn sm-btn--sm">✂ Split</button><button class="sm-btn sm-btn--sm sm-btn--ghost">⧉ Duplicate</button><button class="sm-btn sm-btn--sm sm-btn--ghost">🗑</button><span class="sp"></span><span class="sm-num muted">0:03.40 / 0:12.00</span><span class="sp"></span><span class="dim" style="font-size:11px">Zoom</span><div class="slider" style="width:120px"><i style="width:45%"></i><b style="left:45%"></b></div><button class="sm-btn sm-btn--sm sm-btn--ghost">Fit</button></div>'
  return f'<section class="tl">{bar}<div class="tracks">{r}<div class="ph" style="left:{120+3.4*PX}px"></div></div></section>'
def insp():
  sw="".join(f'<i class="{"on" if i==0 else ""}" style="background:{c}"></i>' for i,c in enumerate(["#ffffff","#a974ff","#45f2f2","#ffb547","#ff5fa2","#0b0a10"]))
  return f'''<aside class="insp"><div class="sm-panel__head">Text <span class="sm-chip sm-chip--hue">Selected</span></div>
<div class="sec"><h4>Style</h4><div class="grid2"><div class="pill on"><b style="font:800 14px var(--font-brand)">Bold Pop</b><span class="dim">Syne 800</span></div><div class="pill"><b>Clean</b><span class="dim">Inter 650</span></div></div>
<label class="sm-field"><span>Font size</span><div class="row"><div class="slider grow"><i style="width:60%"></i><b style="left:60%"></b></div><span class="sm-num muted">64</span></div></label>
<div class="sm-field"><span>Color</span><div class="swatches">{sw}</div></div></div>
<div class="sec"><h4>Animation</h4><div class="sm-seg"><button>None</button><button aria-pressed="true">Pop</button><button>Fade</button><button>Slide</button></div></div>
<div class="sec"><h4>Fade</h4><div class="grid2"><label class="sm-field"><span>In</span><input class="sm-input" value="0.30 s"></label><label class="sm-field"><span>Out</span><input class="sm-input" value="0.50 s"></label></div></div>
<div class="sec"><h4>Position</h4><div class="grid2"><label class="sm-field"><span>X</span><input class="sm-input" value="50%"></label><label class="sm-field"><span>Y</span><input class="sm-input" value="12%"></label></div></div></aside>'''
def textside():
  t="".join(f'<div class="tpl {g} {"on" if i==0 else ""}"><b>{n}</b></div>' for i,(g,n) in enumerate([("g1","Bold Pop"),("g2","Neon Sub"),("g3","Big Title"),("g4","Lower Third")]))
  return f'<aside class="side"><div class="sm-panel__head">Text</div><div class="body"><div class="search">⌕ Search text styles</div><button class="sm-btn sm-btn--lg" style="justify-content:flex-start">＋ Add a heading</button><button class="sm-btn" style="justify-content:flex-start">＋ Add body text</button><div class="lbl">Styles</div><div class="grid2">{t}</div></div></aside>'
right=lambda b="Export":f'{undo}<div class="sm-seg"><button aria-pressed="true">9:16</button><button>1:1</button><button>4:5</button><button>16:9</button></div><button class="sm-btn sm-btn--ghost sm-btn--icon">?</button><button class="sm-btn sm-btn--primary">⇪ {b}</button>'
ed=top("mediasmith","Media",proj,right())+'<div class="shell">'+rail("Text")+textside()+f'<div class="stage"><div class="canvaswrap">{canvas_()}</div><div class="transport"><span class="sm-num muted">0:03.4</span><span class="playbtn">▶</span><span class="sm-num dim">0:12.0</span></div></div>'+insp()+'</div>'+timeline()
page("01-editor","mediasmith",ed)
# home
qa=[("＋","New video","9:16 · 1:1 · 16:9","var(--brand-soft)","var(--brand)"),("CC","Auto-caption","Words timed for you","rgb(255 95 162/.14)","#ff5fa2"),("◎","Make a GIF","From any clip","rgb(255 181 71/.14)","#ffb547"),("⇣","Grab from a link","Paste a URL","rgb(69 242 242/.12)","#45f2f2")]
q="".join(f'<div class="sm-card qa"><div class="ic" style="background:{b};color:{c}">{i}</div><div><b>{t}</b><div class="dim" style="font-size:12px">{s}</div></div></div>' for i,t,s,b,c in qa)
tp="".join(f'<div class="tpl {g}"><b>{n}</b></div>' for g,n in [("g1","Hook + captions"),("g2","Product drop"),("g3","Travel recap"),("g4","Podcast clip"),("g5","Tutorial"),("g6","Quote card")])
pj="".join(f'<div class="sm-card pc"><div class="th {g}"></div><div class="meta"><b>{n}</b><span class="dim" style="font-size:12px">{m}</span></div></div>' for g,n,m in [("g3","Sunset skate edit","Edited 2 min ago · 0:12"),("g2","Launch teaser","Yesterday · 0:30"),("g4","Interview cut","Oct 11 · 1:04"),("g1","Weekend vlog","Oct 9 · 0:45")])
tabs='<div class="sm-seg"><button aria-pressed="true">All</button><button>TikTok</button><button>Reels</button><button>Shorts</button><button>YouTube</button></div>'
home=top("mediasmith","Media","",'<div class="search" style="width:340px">⌕ Search templates and projects</div><button class="sm-btn sm-btn--ghost sm-btn--icon">⚙</button><button class="sm-btn sm-btn--primary">＋ New video</button>')+f'<div class="shell">{rail("Home")}<div class="grow" style="overflow:hidden"><div class="hero"><h1>What are you making <em>today?</em></h1><p class="muted" style="margin:10px 0 0;font-size:15px">Start from a template, or drop a video anywhere on this page.</p></div><div class="quick">{q}</div><div class="secth"><h2>Templates</h2>{tabs}</div><div class="tplrow">{tp}</div><div class="secth"><h2>Recent projects</h2><a class="muted">View all →</a></div><div class="proj">{pj}</div></div></div>'
page("02-home","mediasmith",home)
# export
pres="".join(f'<div class="pill {"on" if i==0 else ""}"><b>{n}</b><span class="dim">{d}</span></div>' for i,(n,d) in enumerate([("TikTok / Reels","1080×1920 · 9:16"),("Feed portrait","1080×1350 · 4:5"),("YouTube","1920×1080 · 16:9"),("GIF","720 px · 15 fps")]))
modal=f'''<div class="sm-backdrop"></div><div class="modalwrap"><div class="sm-dialog" style="width:760px;display:grid;grid-template-columns:260px 1fr;overflow:hidden">
<div style="background:var(--surface-0);display:grid;place-items:center;padding:24px"><div class="canvas" style="height:340px">{'<div class="scene"></div><div class="sun"></div><div class="figure"></div><div class="title" style="font-size:20px">GOLDEN HOUR</div><div class="cap" style="font-size:18px">this is <span class="hl">the</span> part</div>'}</div></div>
<div style="padding:24px;display:grid;gap:16px;align-content:start"><div class="row"><span class="big">Export video</span><span class="sp"></span><button class="sm-btn sm-btn--ghost sm-btn--icon">✕</button></div>
<div class="sm-field"><span>Format</span><div class="grid2">{pres}</div></div>
<div class="sm-field"><span>Quality</span><div class="sm-seg"><button>Draft</button><button aria-pressed="true">High</button><button>Max</button></div></div>
<div class="sm-field"><span>File name</span><input class="sm-input" value="sunset-skate-edit.mp4"></div>
<div class="row muted" style="font-size:12px"><span>≈ 18 MB · 0:12 · H.264 + AAC</span><span class="sp"></span><span>Captions burned in ✓</span></div>
<div class="sm-field"><span>Exporting… 64%  ·  about 8 s left</span><div class="sm-progress"><i style="width:64%"></i></div></div>
<div class="row"><span class="sp"></span><button class="sm-btn">Cancel</button><button class="sm-btn sm-btn--primary sm-btn--lg">⇪ Export</button></div></div></div></div>'''
page("03-export","mediasmith",'<div style="position:relative;flex:1;display:flex;flex-direction:column">'+ed+modal+'</div>')
# standalone helper
def stand(app,pre,glyph,steps,main,side):
  st="".join(f'<span>{"<b>" if i==1 else ""}{i}. {s}{"</b>" if i==1 else ""}</span><span>›</span>' for i,s in enumerate(steps,1))[:-14]
  return top(app,pre,f'<div class="steps">{st}</div>','<button class="sm-btn sm-btn--ghost sm-btn--icon">⚙</button><button class="sm-btn sm-btn--ghost">Open in MediaSmith ↗</button>')+f'<div class="shell"><div class="stage" style="padding:24px 32px;gap:16px">{main}</div><aside class="insp" style="width:340px">{side}</aside></div>'
url='<div class="row"><div class="search grow" style="height:42px;font-size:14px;color:var(--text-2)">🔗 https://youtu.be/dQw-skate-2026</div><button class="sm-btn sm-btn--primary sm-btn--lg">Fetch</button></div>'
clipmain=url+f'<div class="canvaswrap" style="flex:1"><div class="canvas" style="height:auto;width:760px;aspect-ratio:16/9"><div class="scene"></div><div class="sun"></div><div class="figure" style="left:46%"></div></div></div><div class="row"><span class="playbtn">▶</span><span class="sm-num muted">1:12.4</span><span class="sp"></span><span class="sm-chip sm-chip--hue">Clip 0:18.6</span></div><div class="film"><div class="win" style="left:38%;width:22%"></div><div class="ph" style="left:44%"></div></div>'
clipside='<div class="sm-panel__head">Clip</div><div class="sec"><h4>Range</h4><div class="grid2"><label class="sm-field"><span>Start</span><input class="sm-input sm-num" value="1:02.10"></label><label class="sm-field"><span>End</span><input class="sm-input sm-num" value="1:20.70"></label></div></div><div class="sec"><h4>Format</h4><div class="sm-seg"><button aria-pressed="true">MP4</button><button>WebM</button><button>MP3</button><button>WAV</button></div><div class="sm-seg"><button>720p</button><button aria-pressed="true">1080p</button><button>Best</button></div></div><div class="sec"><h4>Crop for</h4><div class="grid2"><div class="pill on"><b>Original</b><span class="dim">16:9</span></div><div class="pill"><b>Vertical</b><span class="dim">9:16 smart crop</span></div></div></div><div class="sec"><div class="sm-toast sm-toast--ok">✓ Ready · 1080p · 24.1 MB</div><button class="sm-btn sm-btn--primary sm-btn--lg">⇣ Save clip</button></div>'
page("04-clipsmith","clipsmith",stand("clipsmith","Clip","[ ]",["Paste link","Trim","Save"],clipmain,clipside))
gifmain='<div class="canvaswrap" style="flex:1"><div class="canvas" style="height:auto;width:640px;aspect-ratio:4/3"><div class="scene"></div><div class="sun"></div><div class="figure"></div><div class="cap" style="font-size:34px">when it <span class="hl">lands</span></div></div></div><div class="row"><span class="sm-chip sm-chip--hue">↻ Loop 2.4 s</span><span class="sm-chip">Ping-pong</span><span class="sp"></span><span class="sm-num muted">frame 18 / 36</span></div><div class="film"><div class="win" style="left:30%;width:16%"></div></div>'
gifside='<div class="sm-panel__head">GIF</div><div class="sec"><h4>Size limit</h4><div class="sm-seg"><button>Discord 10 MB</button><button aria-pressed="true">Slack 5 MB</button><button>Custom</button></div><label class="row" style="font-size:12px"><input type="checkbox" checked> Shrink to fit the limit</label></div><div class="sec"><h4>Quality</h4><label class="sm-field"><span>Width · 480 px</span><div class="slider"><i style="width:48%"></i><b style="left:48%"></b></div></label><label class="sm-field"><span>Frame rate · 15 fps</span><div class="slider"><i style="width:50%"></i><b style="left:50%"></b></div></label><label class="sm-field"><span>Colors · 128</span><div class="slider"><i style="width:50%"></i><b style="left:50%"></b></div></label></div><div class="sec"><h4>Text</h4><input class="sm-input" value="when it lands"></div><div class="sec"><div class="row" style="font-size:12px"><span class="muted">Estimated</span><span class="sp"></span><b class="sm-num">3.8 MB</b><span class="sm-chip" style="color:var(--ok)">fits</span></div><button class="sm-btn sm-btn--primary sm-btn--lg">◎ Make GIF</button></div>'
page("05-gifsmith","gifsmith",stand("gifsmith","Gif","◎",["Choose clip","Tune","Export"],gifmain,gifside))
cues=[("0:00.4","wait for it…","S1"),("0:02.4","this is the part","S1"),("0:04.7","nobody expected that","S2"),("0:07.5","okay run it back","S1"),("0:09.0","follow for part two","S2")]
cl="".join(f'<div class="row" style="padding:10px 12px;border-radius:10px;{"background:var(--app-hue-soft);" if i==1 else ""}"><span class="sm-num dim" style="width:52px">{t}</span><span class="sm-chip" style="color:{"#a974ff" if s=="S1" else "#45f2f2"}">{s}</span><span class="grow">{x}</span></div>' for i,(t,x,s) in enumerate(cues))
capmain=f'<div class="row" style="gap:24px;flex:1;min-height:0"><div class="canvas" style="height:560px"><div class="scene"></div><div class="sun"></div><div class="figure"></div><div class="cap">this <span class="hl">is</span> the part</div></div><div class="sm-panel grow" style="align-self:stretch;display:flex;flex-direction:column"><div class="sm-panel__head">Transcript <span class="sm-chip">2 speakers</span></div><div style="padding:0 8px;display:grid;gap:2px">{cl}</div></div></div>'
capside='<div class="sm-panel__head">Captions</div><div class="sec"><h4>Style</h4><div class="grid2"><div class="pill on"><b style="font:800 13px var(--font-brand)">KARAOKE</b><span class="dim">word highlight</span></div><div class="pill"><b>Subtitle</b><span class="dim">classic</span></div><div class="pill"><b>Boxed</b><span class="dim">high contrast</span></div><div class="pill"><b>Minimal</b><span class="dim">lowercase</span></div></div></div><div class="sec"><h4>Words per line</h4><div class="sm-seg"><button>1</button><button>2</button><button aria-pressed="true">3</button><button>Auto</button></div></div><div class="sec"><h4>Language</h4><input class="sm-input" value="English (auto-detected)"></div><div class="sec"><h4>Export</h4><div class="sm-seg"><button aria-pressed="true">Burn in</button><button>SRT</button><button>VTT</button><button>ASS</button></div><button class="sm-btn sm-btn--primary sm-btn--lg">CC Export captions</button></div>'
page("06-captionsmith","captionsmith",stand("captionsmith","Caption","CC",["Add video","Review","Export"],capmain,capside))
# logos
L="".join(f'<div style="display:grid;justify-items:center;gap:18px"><img src="../../../../packages/ui/src/brand/{a}.svg" width="220"><span class="sm-wordmark" style="font-size:26px"><span><span class="app" style="color:{h}">{p}</span><span class="smith">Smith</span></span></span><div class="row"><img src="../../../../packages/ui/src/brand/{a}.svg" width="48"><img src="../../../../packages/ui/src/brand/{a}.svg" width="32"><img src="../../../../packages/ui/src/brand/{a}.svg" width="16"></div></div>' for a,p,h in [("mediasmith","Media","#a974ff"),("clipsmith","Clip","#45f2f2"),("gifsmith","Gif","#ffb547"),("captionsmith","Caption","#ff5fa2")])
page("07-logos","mediasmith",f'<div style="flex:1;display:grid;align-content:center;gap:56px;background:radial-gradient(ellipse at 50% 0%,#1a1626,var(--surface-0) 70%)"><div style="text-align:center"><h1 style="margin:0;font:800 44px var(--font-brand)">The <span style="background:var(--brand-grad);-webkit-background-clip:text;color:transparent">Smith</span> suite</h1><p class="muted">One frame, one spark, four hues.</p></div><div style="display:flex;justify-content:center;gap:72px">{L}</div></div>')
